def transform(grid):
    out = [row[:] for row in grid]
    anchors = [(r, c) for r, row in enumerate(grid)
               for c, v in enumerate(row) if v == 5]
    if len(anchors) < 2:
        return out

    # The patterned 5 is the source anchor; the isolated 5 is the target.
    def neighbors(anchor):
        r, c = anchor
        return sum(
            1 for y in range(max(0, r - 2), min(len(grid), r + 3))
            for x in range(max(0, c - 2), min(len(grid[0]), c + 3))
            if (y, x) != anchor and grid[y][x] != 0
        )

    source = max(anchors, key=neighbors)
    target = min(anchors, key=neighbors)
    dr, dc = target[0] - source[0], target[1] - source[1]
    out[target[0]][target[1]] = 0

    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value and (r, c) != source and (r, c) != target:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(row):
                    out[nr][nc] = value

    return out
